  `${slackSafe(p.lead.name || 'Unnamed lead')}: ${p.lead.intent}, urgency ${p.lead.urgency}/5, from ${slackSafe(p.lead.source)}`,
  p.lead.summary ? `> ${slackSafe(p.lead.summary)}` : '',
  outcome,
  `Open in monday: ${p.itemUrl}`,
].filter(Boolean).join('\n');
return $env.SLACK_WEBHOOK_URL ? [{ json: { text }, pairedItem: { item: 0 } }] : [];
